import { z } from 'zod'

import { externalLinksSchema } from './validator'

/**
 * zod schemas for the generated species-index files:
 *
 * - `data/species/index.json` — the cross-ecosystem listing of all species
 * - `data/species/entries/<slug>.json` — one file per grouped species
 *
 * Both are generated by `scripts/pipeline/build_species_index.py`
 * (`npm run build:species-index`) — never hand-edited. These schemas are the
 * exact contract the generator emits; they are deliberately separate from
 * `ecosystemWebSchema`.
 */

const idSchema = z
  .string()
  .regex(/^[a-z0-9]+(-[a-z0-9]+)*$/, 'expected a kebab-case id')

const nodeKindSchema = z.enum(['functional-group', 'species', 'life-stage-group'])

/** One (web, node) pair where a species entry occurs. */
export const speciesOccurrenceSchema = z
  .object({
    web: idSchema,
    node: idSchema,
  })
  .strict()

export const speciesIndexEntrySchema = z
  .object({
    slug: idSchema,
    name: z.string().min(1),
    kind: nodeKindSchema,
    webs: z.array(idSchema),
    occurrences: z.array(speciesOccurrenceSchema),
  })
  .strict()

/** data/species/index.json — the cross-ecosystem species listing. */
export const speciesIndexSchema = z
  .object({
    webCount: z.number().int().min(0),
    entryCount: z.number().int().min(0),
    entries: z.array(speciesIndexEntrySchema),
  })
  .strict()

/** One occurrence of a species entry, with the web context the index page shows. */
export const speciesEntryOccurrenceSchema = z
  .object({
    web: z.string().min(1),
    webName: z.string().min(1),
    biome: z.string().min(1),
    node: idSchema,
    displayName: z.string().min(1),
    kind: nodeKindSchema,
    trophicLevel: z.number().min(1),
    externalLinks: externalLinksSchema.optional(),
  })
  .strict()

/** data/species/entries/<slug>.json — one grouped species across webs. */
export const speciesEntrySchema = z
  .object({
    slug: idSchema,
    name: z.string().min(1),
    kind: nodeKindSchema,
    description: z.string().min(1),
    sourceWeb: idSchema,
    externalLinks: externalLinksSchema.optional(),
    notes: z.array(z.string().min(1)).optional(),
    occurrences: z.array(speciesEntryOccurrenceSchema),
  })
  .strict()

export type SpeciesOccurrence = z.infer<typeof speciesOccurrenceSchema>
export type SpeciesIndexEntry = z.infer<typeof speciesIndexEntrySchema>
export type SpeciesIndex = z.infer<typeof speciesIndexSchema>
export type SpeciesEntryOccurrence = z.infer<typeof speciesEntryOccurrenceSchema>
export type SpeciesEntry = z.infer<typeof speciesEntrySchema>

/** Parse and validate an unknown value as a SpeciesIndex; throws ZodError. */
export function parseSpeciesIndex(data: unknown): SpeciesIndex {
  return speciesIndexSchema.parse(data)
}

/** Parse and validate an unknown value as a SpeciesEntry; throws ZodError. */
export function parseSpeciesEntry(data: unknown): SpeciesEntry {
  return speciesEntrySchema.parse(data)
}
